use v5.42;
use strict;
use warnings;
use JSON::PP 'decode_json';
use Digest::SHA 'sha256_hex';
use File::Temp 'tempfile';
use lib 'bench/lib';
use Wump::BenchMatrix qw(load_capture compare);
sub contents ($path) {open my $in,'<',$path or die "$path: $!"; binmode $in; local $/; my $text=<$in>; close $in or die $!; return $text}
sub historical ($revision,$path) {
 open my $in,'-|','git','show',"$revision:$path" or die $!;
 my $bytes=do {local $/; <$in>}; close $in or die 'historical source unavailable';
 return $bytes;
}
my $m=decode_json(contents('bench/operation-matrix-machine.json'));
my $after=load_capture('bench/operation-matrix-current.json');
my $anchor=load_capture('bench/operation-matrix-baseline.json');
my ($failed,$report)=compare($anchor,$after,10);
$report eq contents('bench/operation-matrix-check.txt') or die 'incorrect default gate report';
print "ok - default retained-anchor gate status $failed\n";
my %previous;
for my $name (sort keys %{$m->{historical_comparisons}}) {
 my $spec=$m->{historical_comparisons}{$name};
 my $bytes=historical($spec->{revision},$spec->{path});
 sha256_hex($bytes) eq $spec->{capture_sha256} or die 'wrong historical capture hash';
 my ($out,$path)=tempfile(UNLINK=>1);
 print {$out} $bytes or die $!; close $out or die $!;
 my $capture=load_capture($path);
 my ($status,$text)=compare($capture,$after,10);
 $text eq $spec->{report} or die 'incorrect historical gate report';
 my $failures=()=$text=~/^FAIL /mg;
 print "ok - $name saved exactly; gate status $status ($failures failed metrics)\n";
 $previous{$name}=$capture;
}
my $before=$previous{previous_bindings};
my $fixture=sha256_hex(join '',map {contents($_)} qw(bench/matrix.pl bench/matrix-worker.pl bench/matrix-worker.go bench/lib/Wump/BenchMatrix.pm));
for my $capture ($before,$after) {
 my @samples=map {@{$_->{samples}}} @{$capture->{cells}};
 @samples==770 && grep($_->{status} eq 'ok',@samples)==650 && !$capture->{source}{dirty}
  && $capture->{source}{fixture_sha256} eq $fixture or die 'invalid matrix provenance/completion';
}
for my $control (qw(stock go)) {$before->{binaries}{$control}{sha256} eq $after->{binaries}{$control}{sha256} or die 'control changed'}
$m->{source_revision} eq $after->{source}{revision} && $m->{before_source_revision} eq $before->{source}{revision} or die 'wrong harness sources';
for my $path (keys %{$m->{sha256}}) {
 my $bytes=$path =~ m{^/} ? contents($path) : historical($m->{source_revision},$path);
 sha256_hex($bytes) eq $m->{sha256}{$path} or die "changed source/binary/archive: $path";
}
for my $field (qw(validation_log_sha256 diagnostic_triage_sha256 profile_artifact_sha256 retained_sha256)) {
 for my $path (keys %{$m->{$field}}) {sha256_hex(contents($path)) eq $m->{$field}{$path} or die "changed evidence: $path"}
}
for my $role (keys %{$m->{runtime_archive_members}}) {
 for my $name (keys %{$m->{runtime_archive_members}{$role}}) {
  my $root='/home/marcus/projects/wump/master/build/checkpoint-reclamation';
  open my $in,'-|','ar','p',"$root/$role/perl/perl-5.42.2/libperl.a","$name.o" or die $!;
  my $bytes=do {local $/; <$in>}; close $in or die 'archive extraction failed';
  sha256_hex($bytes) eq $m->{runtime_archive_members}{$role}{$name} or die 'stale runtime archive';
 }
}
$m->{binaries}{before}{sha256} eq $before->{binaries}{wump}{sha256} && $m->{binaries}{current}{sha256} eq $after->{binaries}{wump}{sha256} or die 'wrong paired binaries';
print "ok - all 1540 paired samples, source/binary/archive/log hashes and exact reports verified\n";
